using System; using System.Collections.Generic; using System.ComponentModel.DataAnnotations; using System.ComponentModel.DataAnnotations.Schema;
namespace MaSV_LTW_MyStore.Models {
 [Table("User")] public class StoreUser { [Key, StringLength(255)] public string Username {get;set;} [Required, StringLength(50)] public string Password {get;set;} [Required, StringLength(1)] public string UserRole {get;set;} }
 [Table("Customer")] public class Customer { [Key, DatabaseGenerated(DatabaseGeneratedOption.Identity)] public int CustomerID {get;set;} [Required] public string CustomerName {get;set;} [Required, StringLength(15)] public string CustomerPhone {get;set;} public string CustomerEmail {get;set;} public string CustomerAddress {get;set;} [Required, StringLength(255)] public string Username {get;set;} [ForeignKey("Username")] public virtual StoreUser User {get;set;} public virtual ICollection<StoreOrder> Orders {get;set;} }
 [Table("Category")] public class Category { [Key, DatabaseGenerated(DatabaseGeneratedOption.Identity)] public int CategoryID {get;set;} [Required] public string CategoryName {get;set;} public virtual ICollection<Product> Products {get;set;} }
 [Table("Product")] public class Product { [Key, DatabaseGenerated(DatabaseGeneratedOption.Identity)] public int ProductID {get;set;} public int CategoryID {get;set;} [Required] public string ProductName {get;set;} [Required] public string ProductDecription {get;set;} [Range(0,999999999)] public decimal ProductPrice {get;set;} public string ProductImage {get;set;} [ForeignKey("CategoryID")] public virtual Category Category {get;set;} }
 [Table("Order")] public class StoreOrder { [Key, DatabaseGenerated(DatabaseGeneratedOption.Identity)] public int OrderID {get;set;} public int CustomerID {get;set;} public DateTime OrderDate {get;set;} public decimal TotalAmount {get;set;} public string PaymentStatus {get;set;} [Required] public string AddressDelivery {get;set;} [ForeignKey("CustomerID")] public virtual Customer Customer {get;set;} public virtual ICollection<OrderDetail> Details {get;set;} }
 [Table("OrderDetail")] public class OrderDetail { [Key, DatabaseGenerated(DatabaseGeneratedOption.Identity)] public int ID {get;set;} public int ProductID {get;set;} public int OrderID {get;set;} public int Quantity {get;set;} public decimal UnitPrice {get;set;} [ForeignKey("ProductID")] public virtual Product Product {get;set;} [ForeignKey("OrderID")] public virtual StoreOrder Order {get;set;} }
}
